"""generated by derivations/dirac_pulsation.py: coefficients of the linearised Dirac-star pulsation equations
   row = sum_j A[j] y_j + B[j] y_j',  y = (uR, uI, vR, vI, dX, dphi);  rows uR..vI give lambda y_k, ham gives dX', sli gives dphi'
   arguments: r, w, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU (potential at the background S)"""
import numpy as np
from numpy import exp, sqrt, pi

def uR(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [(0) + z, (dU*exp(phi0) - dg*g*r*exp(phi0) + mu*exp(phi0) - omega) + z, (0) + z, ((-X0*df*g*r**2 - X0 - 1/2*dphi0*r - 1)*exp(phi0)/(X0*r)) + z, (0) + z, (0) + z]
    B = [(0) + z, (g**2*r*exp(phi0)) + z, (0) + z, ((X0*f*g*r - 1)*exp(phi0)/X0) + z, (0) + z, (0) + z]
    return A, B

def uI(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [(-dU*exp(phi0) - ddU*g**2*exp(phi0)/pi - mu*exp(phi0) + omega) + z, (0) + z, ((X0*ddU*f*g*r + pi*X0 + (1/2)*pi*dphi0*r + pi)*exp(phi0)/(pi*X0*r)) + z, (0) + z, ((-f - 1/2*r*(2*df + dphi0*f))*exp(phi0)/(X0**2*r)) + z, ((X0*f - X0*g*r*(dU + mu) + f + (1/2)*r*(2*df + dphi0*f))*exp(phi0)/(X0*r)) + z]
    B = [(0) + z, (0) + z, (exp(phi0)/X0) + z, (0) + z, (0) + z, ((1/2)*f*exp(phi0)/X0) + z]
    return A, B

def vR(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [(0) + z, ((-X0*dg*f*r**2 - X0 + (1/2)*dphi0*r + 1)*exp(phi0)/(X0*r)) + z, (0) + z, (-dU*exp(phi0) - df*f*r*exp(phi0) - mu*exp(phi0) - omega) + z, (0) + z, (0) + z]
    B = [(0) + z, ((X0*f*g*r + 1)*exp(phi0)/X0) + z, (0) + z, (f**2*r*exp(phi0)) + z, (0) + z, (0) + z]
    return A, B

def vI(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [((X0*ddU*f*g*r + pi*X0 - 1/2*pi*dphi0*r - pi)*exp(phi0)/(pi*X0*r)) + z, (0) + z, (dU*exp(phi0) - ddU*f**2*exp(phi0)/pi + mu*exp(phi0) + omega) + z, (0) + z, ((g + (1/2)*r*(2*dg + dphi0*g))*exp(phi0)/(X0**2*r)) + z, ((X0*f*r*(dU + mu) + X0*g - g - 1/2*r*(2*dg + dphi0*g))*exp(phi0)/(X0*r)) + z]
    B = [(-exp(phi0)/X0) + z, (0) + z, (0) + z, (0) + z, (0) + z, (-1/2*g*exp(phi0)/X0) + z]
    return A, B

def ham(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [(2*X0**2*(2*X0*dU*g*r - 2*X0*f + 2*X0*g*mu*r - df*r)) + z, (0) + z, (2*X0**2*(-2*X0*dU*f*r - 2*X0*f*mu*r - 2*X0*g + dg*r)) + z, (0) + z, ((1/2)*(-3*X0**2 + 4*X0*r*(6*pi*U*X0*r - 3*X0*f**2*mu*r - 6*X0*f*g + 3*X0*g**2*mu*r - 2*df*g*r + 2*dg*f*r) + 1)/r) + z, (0) + z]
    B = [(2*X0**2*f*r) + z, (0) + z, (-2*X0**2*g*r) + z, (0) + z, (0) + z, (0) + z]
    return A, B

def sli(r, omega, mu, g, f, dg, df, X0, phi0, dphi0, U, dU, ddU):
    z = np.zeros_like(r)
    A = [(2*X0*r*(-X0*ddU*f**2*g + X0*ddU*g**3 - pi*df)/pi) + z, (0) + z, (2*X0*r*(X0*ddU*f**3 - X0*ddU*f*g**2 + pi*dg)/pi) + z, (0) + z, ((X0 + 2*r**2*(-4*pi*U*X0 - 2*X0*dU*f**2 + 2*X0*dU*g**2 - df*g + dg*f))/r) + z, (0) + z]
    B = [(2*X0*f*r) + z, (0) + z, (-2*X0*g*r) + z, (0) + z, (0) + z, (0) + z]
    return A, B
